const countEl = document.getElementById('count');
let count = 0;

function render() {
  countEl.textContent = count;
}

document.getElementById('increment').addEventListener('click', () => {
  count += 1;
  render();
});

document.getElementById('decrement').addEventListener('click', () => {
  count -= 1;
  render();
});

render();

