const {test, assert} = require('./browser.cjs');

test('Increment and decrement the count', async (page) => {
  const countEl = page.getByTestId('count');
  await assert.equal(await countEl.textContent(), '0', 'initial count is 0');

  const incBtn = page.getByRole('button', {name: 'Increment'});
  const decBtn = page.getByRole('button', {name: 'Decrement'});
  await assert.ok(await incBtn.isVisible(), 'Increment button is visible');
  await assert.ok(await decBtn.isVisible(), 'Decrement button is visible');

  await incBtn.click();
  await incBtn.click();
  await assert.equal(await countEl.textContent(), '2', 'count is 2 after two increments');

  await decBtn.click();
  await decBtn.click();
  await decBtn.click();
  await assert.equal(await countEl.textContent(), '-1', 'count is -1 after three decrements');
});
